# The context variable contains documents. We will scan each document with a sub-LLM
# to find any cricket match that satisfies all the user's constraints, extract the
# match number, tournament name, and year, and then consolidate to a single final answer.

candidate_summaries = ""
for d in context:
    prompt = "You are given a document. It may describe one or more cricket matches. Your task: Identify any match(es) that satisfy ALL of these constraints:\n\nC1: The team that batted first won the match by a margin between 20 and 30 runs inclusive.\nC2: Both teams batted their full allocation of overs (e.g., 20 overs in T20, 50 overs in ODI).\nC3: The two opening batsmen of the winning team combined scored between 50 and 60 runs inclusive.\nC4: The two opening batsmen of the losing team combined scored between 60 and 70 runs inclusive.\nC5: The highest and second-highest run-scorers for the winning team hit an equal number of fours (4s) in the match.\nC6: The second-highest run-scorer for the winning team was awarded Player of the Match.\nC7: The losing team scored more than 10 runs in the final over of their innings.\nC8: One of the losing team's openers was dismissed by the Player of the Match.\n\nFrom the document, extract, for any match that meets ALL constraints C1–C8:\n- tournament name\n- year of tournament\n- match number within the tournament (e.g., \"Match 23\")\n- teams and which one batted first\n- winning team and margin\n- the two openers and runs for each team (clearly identify who opened and their runs)\n- top two run-scorers for the winning team with their runs and number of fours (4s)\n- Player of the Match and his bowling figures and wickets; explicitly state if he dismissed any opener of the losing team and who\n- confirm both teams faced all overs\n- runs scored in the final over of the losing team's chase\nProvide direct quotes (exact sentences/lines) from the document backing each extracted item.\n\nImportant:\n- Only output matches where ALL constraints C1–C8 can be confirmed True from the document.\n- If the document does not contain a match that satisfies all constraints, output nothing.\n\nOutput format for each matching match:\nBEGIN_MATCH\nMatch number: <match number as written in the document>\nTournament: <tournament name as written>\nYear: <year>\nVerification:\n- C1: True — <quote(s)>\n- C2: True — <quote(s)>\n- C3: True — <quote(s)>\n- C4: True — <quote(s)>\n- C5: True — <quote(s)>\n- C6: True — <quote(s)>\n- C7: True — <quote(s)>\n- C8: True — <quote(s)>\nEND_MATCH\n\nDocument:\nBEGIN_DOCUMENT\n" + d + "\nEND_DOCUMENT"
    res = llm_query(prompt)
    candidate_summaries = candidate_summaries + res + "\n\n"

final_prompt = "You are given zero or more extracted matches below. Each BEGIN_MATCH..END_MATCH block already satisfies all constraints. Your task: extract the match number, tournament name, and the year.\n\nIf exactly one matching match is present, return exactly one line in the format:\nMatch <number>, <Tournament>, <Year>\n\nIf multiple matching matches are present, choose the one with the clearest verification quotes; if still tied, choose the first. Return exactly one line in the same format.\nIf no matching match is present, return:\nNot found\n\nExtracted matches:\n" + candidate_summaries

final_answer = llm_query(final_prompt)
return_result(final_answer)